{"file_path":"src/errors.js","content":"/** Failures that the command reports itself, with the exit code they carry. */
export class AppError extends Error {
  constructor(message, code) {
    super(message)
    this.name = 'AppError'
    this.code = code
  }
}

/** A validation failure: one line on standard error and exit 2. */
export function fail(message) {
  return new AppError(message, 2)
}

/** An unschedulable graph: one line on standard error and exit 3. */
export function cycleError(names) {
  return new AppError(`cycle: ${[...names, names[0]].join(' -> ')}`, 3)
}
"}

