const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/** The lines of the input, with the empty tail a trailing newline leaves dropped. */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function checkName(name, lineNo) {
  if (!NAME.test(name)) throw fail(`line ${lineNo}: invalid task name ${name}`)
}

/**
 * Reads a build graph. Returns a Map from name to { name, cost, deps }, where
 * deps is an array of distinct dependency names in the order they appeared.
 */
export function parseGraph(text) {
  const lines = splitLines(text)
  const tasks = new Map()
  const edges = []
  const references = []

  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw fail(`line ${lineNo}: expected task <name> <cost>`)
      const [, name, cost] = words
      checkName(name, lineNo)
      if (!COST.test(cost)) throw fail(`line ${lineNo}: cost must be a non-negative integer`)
      if (tasks.has(name)) throw fail(`line ${lineNo}: task ${name} is declared twice`)
      tasks.set(name, { name, cost: Number(cost), deps: [] })
    } else if (directive === 'dep') {
      if (words.length < 3) throw fail(`line ${lineNo}: expected dep <name> <dependency>...`)
      for (const word of words.slice(1)) checkName(word, lineNo)
      const name = words[1]
      references.push(name)
      for (const dependency of words.slice(2)) {
        references.push(dependency)
        edges.push([name, dependency])
      }
    } else {
      throw fail(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of references) {
    if (!tasks.has(name)) throw fail(`unknown task ${name}`)
  }

  for (const [name, dependency] of edges) {
    const task = tasks.get(name)
    if (!task.deps.includes(dependency)) task.deps.push(dependency)
  }

  return tasks
}
"}

