/** The task names in ascending order. */
export function sortedNames(tasks) {
  return [...tasks.keys()].sort()
}

/**
 * Walks the graph depth first, from each task in ascending name order and
 * through each task's dependencies in ascending name order. Throws on the first
 * cycle found; otherwise returns the tasks in an order where every task follows
 * all of its dependencies.
 */
export function topologicalOrder(tasks) {
  const order = []
  const state = new Map() // 'open' while on the search stack, 'done' once left
  const deps = new Map()
  for (const name of sortedNames(tasks)) deps.set(name, [...tasks.get(name).deps].sort())

  for (const root of sortedNames(tasks)) {
    if (state.has(root)) continue
    const path = [root]
    const frames = [{ name: root, index: 0 }]
    state.set(root, 'open')
    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      const children = deps.get(frame.name)
      if (frame.index < children.length) {
        const child = children[frame.index]
        frame.index += 1
        const seen = state.get(child)
        if (seen === 'open') throw cycleError(path.slice(path.indexOf(child)))
        if (seen === undefined) {
          state.set(child, 'open')
          path.push(child)
          frames.push({ name: child, index: 0 })
        }
      } else {
        state.set(frame.name, 'done')
        order.push(frame.name)
        path.pop()
        frames.pop()
      }
    }
  }
  return order
}

/**
 * The start, finish and depth of every task, assuming unlimited workers, plus
 * the resulting makespan.
 */
export function analyse(tasks, order) {
  const info = new Map()
  let total = 0
  for (const name of order) {
    const task = tasks.get(name)
    let start = 0
    let depth = 0
    for (const dependency of task.deps) {
      const other = info.get(dependency)
      if (other.finish > start) start = other.finish
      if (other.depth + 1 > depth) depth = other.depth + 1
    }
    const finish = start + task.cost
    info.set(name, { name, start, finish, depth })
    if (finish > total) total = finish
  }
  return { info, total }
}

/** The waves: wave K holds every task whose deepest dependency sits in wave K-1. */
export function waves(tasks, info) {
  const grouped = []
  for (const name of sortedNames(tasks)) {
    const { depth } = info.get(name)
    while (grouped.length <= depth) grouped.push([])
    grouped[depth].push(name)
  }
  return grouped
}

/**
 * The priority of every task: the cost of the longest chain that begins at it,
 * counting its own cost and then the costs down to a task nothing depends on.
 */
export function priorities(tasks, order) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const task of tasks.values()) {
    for (const dependency of task.deps) dependents.get(dependency).push(task.name)
  }
  const priority = new Map()
  for (let i = order.length - 1; i >= 0; i -= 1) {
    const name = order[i]
    let best = 0
    for (const dependent of dependents.get(name)) {
      const value = priority.get(dependent)
      if (value > best) best = value
    }
    priority.set(name, tasks.get(name).cost + best)
  }
  return priority
}
