/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'
import { AppError, fail } from './errors.js'
import { parseGraph } from './parse.js'
import { analyse, priorities, sortedNames, topologicalOrder, waves } from './graph.js'
import { pack } from './schedule.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'

function parseArguments(argv) {
  if ((argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain'))) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) throw fail('workers must be a positive integer')
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw fail(USAGE)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function render(options, tasks) {
  const order = topologicalOrder(tasks)
  const lines = []

  if (options.mode === 'pack') {
    const { runs, makespan } = pack(tasks, priorities(tasks, order), options.workers)
    runs.forEach((runsOfWorker, index) => {
      const parts = runsOfWorker.map((run) => ` ${run.name}@${run.start}-${run.finish}`)
      lines.push(`worker ${index}:${parts.join('')}`)
    })
    lines.push(`makespan ${makespan}`)
    return lines
  }

  const { info, total } = analyse(tasks, order)
  if (options.mode === 'waves') {
    waves(tasks, info).forEach((names, index) => lines.push(`wave ${index}: ${names.join(' ')}`))
  } else {
    for (const name of sortedNames(tasks)) {
      const { start, finish, depth } = info.get(name)
      lines.push(`${name} start=${start} finish=${finish} depth=${depth}`)
    }
  }
  lines.push(`total ${total}`)
  return lines
}

function main() {
  const options = parseArguments(process.argv.slice(2))
  const tasks = parseGraph(readStdin())
  return render(options, tasks)
}

try {
  const lines = main()
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
} catch (error) {
  if (error instanceof AppError) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(error.code)
  }
  throw error
}
"}

